from taf.gnb.oam.coam.vdu.schemas.base.schema_common import SchemaField, SchemaObject


class DistNames(SchemaObject):
    config = SchemaField(name="config")
    runtime = SchemaField(name="runtime")

    def __init__(self, config, runtime):
        self.config = config
        self.runtime = runtime

        super(DistNames, self).__init__()


class AntPorts(SchemaObject):
    id = SchemaField(name="id")
    name = SchemaField(name="name")
    direction = SchemaField(name="direction")
    dist_names = SchemaField(name="dist_names", klass=DistNames)

    def __init__(self, id, name, direction, dist_names):
        self.id = id
        self.name = name
        self.direction = direction
        self.dist_names = dist_names

        super(AntPorts, self).__init__()


class RmodsStatus(SchemaObject):
    id = SchemaField(name="id")
    configuration_id = SchemaField(name="configuration_id")
    product_name = SchemaField(name="product_name")
    product_code = SchemaField(name="product_code")
    serial_number = SchemaField(name="serial_number")
    hardware_version = SchemaField(name="hardware_version")
    hardware_release = SchemaField(name="hardware_release")
    technology_type = SchemaField(name="technology_type")
    mimo_type = SchemaField(name="mimo_type")
    administrative_state = SchemaField(name="administrative_state")
    operational_state = SchemaField(name="operational_state")
    availability_status = SchemaField(name="availability_status")
    ant_ports = SchemaField(name="ant_ports", klass=AntPorts, many=True)
    procedural_status = SchemaField(name="procedural_status")
    cell_ids = SchemaField(name="cell_ids")
    active_sw_build = SchemaField(name="active_sw_build")
    active_sw_version = SchemaField(name="active_sw_version")
    interface_type = SchemaField(name="interface_type")
    dist_names = SchemaField(name="dist_names", klass=DistNames)
    power_state = SchemaField(name="power_state", optional=True)

    def __init__(self, id, configuration_id, product_name, product_code, serial_number, hardware_version,
                 hardware_release, technology_type, mimo_type, administrative_state, operational_state,
                 availability_status, ant_ports, procedural_status, cell_ids, active_sw_build, active_sw_version,
                 interface_type, dist_names, power_state):
        self.id = id
        self.configuration_id = configuration_id
        self.product_name = product_name
        self.product_code = product_code
        self.serial_number = serial_number
        self.hardware_version = hardware_version
        self.hardware_release = hardware_release
        self.technology_type = technology_type
        self.mimo_type = mimo_type
        self.administrative_state = administrative_state
        self.operational_state = operational_state
        self.availability_status = availability_status
        self.ant_ports = ant_ports
        self.interface_type = interface_type
        self.dist_names = dist_names
        self.procedural_status = procedural_status
        self.cell_ids = cell_ids
        self.active_sw_build = active_sw_build
        self.active_sw_version = active_sw_version
        self.power_state = power_state

        super(RmodsStatus, self).__init__()
